exercises.solution:
def make_account(balance, password):
    def withdraw(amount):
        nonlocal balance
        if amount <= balance:
            balance -= amount
            return balance
        return "Insufficient funds"

    def deposit(amount):
        nonlocal balance
        balance += amount
        return balance

    def dispatch(pw, message):
        if pw != password:
            return "Incorrect password"
        if message == "withdraw":
            return withdraw
        if message == "deposit":
            return deposit
        raise ValueError(f"Unknown request: {message}")

    return dispatch
